import requests
try:
    r = requests.get('https://api.example.com/users/9999', timeout=5)
    r.raise_for_status()
    print(r.json())
except requests.exceptions.Timeout:
    print('slow')
except requests.exceptions.HTTPError:
    print('http error')
except requests.exceptions.RequestException as e:
    print(f'fail: {e}')
